#!/usr/bin/env node
const fs = require('fs');
const path = require('path');

const ROOT = path.join(__dirname, '..', '..', '..', '..', '..');
const IN_MD = path.join(ROOT, '001 banco de retos de empatia.md');
const OUT_JSON = path.join(__dirname, '..', 'data', 'empatia-challenges.json');
const OUT_JS = path.join(__dirname, '..', 'data', 'empatia-challenges.js');

const CHALLENGE_RE = /^- \*\*Challenge (\d+) \[([^\]]+)\]\*\*: (.+)$/;
const TSN_RE = /^\s+- \*\*TSN\*\*: (.+)$/;

function skillLevelForChallenge(globalNumber) {
    if (globalNumber <= 20) return 1;
    if (globalNumber <= 40) return 2;
    return 3;
}

function bankLevelForChallenge(globalNumber) {
    return skillLevelForChallenge(globalNumber);
}

function numberWithinBank(globalNumber) {
    const bank = bankLevelForChallenge(globalNumber);
    return globalNumber - (bank - 1) * 20;
}

function parseMarkdown(content) {
    const challenges = [];
    const lines = content.split(/\r?\n/);
    let current = null;

    const flush = () => {
        if (!current) return;
        const textParts = [`[${current.title}] ${current.body}`];
        if (current.tsn) textParts.push(`TSN: ${current.tsn}`);
        challenges.push({
            bankLevel: current.bankLevel,
            number: current.number,
            globalNumber: current.globalNumber,
            title: current.title,
            text: textParts.join('\n\n'),
            skillLevel: current.skillLevel
        });
        current = null;
    };

    lines.forEach(line => {
        const challengeMatch = line.match(CHALLENGE_RE);
        if (challengeMatch) {
            flush();
            const globalNumber = Number(challengeMatch[1]);
            current = {
                globalNumber,
                title: challengeMatch[2].trim(),
                body: challengeMatch[3].trim(),
                tsn: '',
                bankLevel: bankLevelForChallenge(globalNumber),
                number: numberWithinBank(globalNumber),
                skillLevel: skillLevelForChallenge(globalNumber)
            };
            return;
        }

        const tsnMatch = line.match(TSN_RE);
        if (tsnMatch && current) {
            current.tsn = tsnMatch[1].trim();
        }
    });

    flush();
    return challenges;
}

if (!fs.existsSync(IN_MD)) {
    console.error(`Missing markdown file: ${IN_MD}`);
    process.exit(1);
}

const markdown = fs.readFileSync(IN_MD, 'utf8');
const challenges = parseMarkdown(markdown);

if (challenges.length !== 60) {
    console.error(`Expected 60 challenges, parsed ${challenges.length}`);
    process.exit(1);
}

const missingTsn = challenges.filter(c => !c.text.includes('TSN:'));
if (missingTsn.length > 0) {
    console.error(`Missing TSN on challenges: ${missingTsn.map(c => c.globalNumber).join(', ')}`);
    process.exit(1);
}

fs.writeFileSync(OUT_JSON, JSON.stringify(challenges, null, 2), 'utf8');
fs.writeFileSync(
    OUT_JS,
    `/* Auto-generated by dev/scripts/generate-empatia-data.js */\nconst EMPATIA_CHALLENGES = ${JSON.stringify(challenges, null, 2)};\n\nmodule.exports = { EMPATIA_CHALLENGES };\n`,
    'utf8'
);

console.log(`Generated ${challenges.length} empatia challenges`);
